import React, { useEffect, useState } from 'react';
import '../scss/my.scss'
import ImageGallery from "react-image-gallery";
import "react-image-gallery/styles/css/image-gallery.css"


const Banner = (props)=>{

    useEffect(() => {
        window.scrollTo(0, 0);
      }, []);
      
    const data = props.dbtads;

    const images4 = props.dbgal4;
    
    const images5 = props.dbgal5;

    const [menu, setMenu] = useState('banner')
    const [activeButton, setActiveButton] = useState('banner');
    const [activeButton2, setActiveButton2] = useState('page');

    let menuContent 






    if (menu === 'banner') {
            menuContent = (
                <div>
                    <ImageGallery items={images4} infinite='true'/>     
                </div>
                ); 
    }else if(menu === 'page'){
        menuContent = (
            <div>
                {images5.map((v,i)=>(
                    <img className={v.cls} src={v.original} alt={v.originalAlt} />
                ))}   
            </div>
            );
    }

    const handlebannerButtonClick = () => {
        setActiveButton('banner');
        setMenu('banner');
      };

    const handleMenusButtonClick = () => {
        setActiveButton('page');
        setMenu('page');
      };

    return(
        <section id="banner">
                    {data.tban.map((v,i)=>(
                    <ul id="bar" key={v.id}>
                        <li>{v.title}</li>
                        <li>
                            <button onClick={handlebannerButtonClick} className={`${v.btn1cls} ${activeButton === 'banner' ? 'active' : ' '}`}>{v.btn1}</button>
                            <button onClick={handleMenusButtonClick} className={`${v.btn2cls} ${activeButton === 'page' ? 'active' : ' '}`}>{v.btn2}</button>
                        </li>
                    </ul>
                    ))}
            <ul id="display">
                            <li className='show'>        
                                {menuContent}
                            </li>
            </ul>
        </section>
    )
}

export default Banner;
